    fn javascript_files_may_contain_jsx() {
        let analysis = analyze_source("view.js", "export const v = <div />;\n", AnalysisProfile::Full);
        assert!(!analysis.had_parse_errors);
        assert_eq!(analysis.jsx_elements().len(), 1);
    }

