export const api = {
  version: 1,
  async load(id: string): Promise<User> {
    return get(id);
  },
  save: (user: User) => {
    put(user);
  },
  fetch: async function (url: string) {
    return url;
  },
  get name(): string {
    return 'x';
  },
  set name(value: string) {
    store(value);
  },
  short() { return 1; },
  alias: (a: number) => a + 1,
  two: () => {
  },
  data: {
    nested() {
      return 1;
    },
  },
  ...rest,
};
